command:
set -euo pipefail
W=/workspace/go-avatar-gpt56-20260912-0636
ROOT=$(find "$W/all" -type f -name buehne.html -path '*ROUND1_EXPORT*' -printf '%h\n' | head -1)
test -n "$ROOT"
export ROOT
python3 - <<'PY'
import os, pathlib, hashlib
p=pathlib.Path(os.environ['ROOT'])/'buehne.html'
s=p.read_text(encoding='utf-8'); orig=s
backup=pathlib.Path(os.environ['ROOT'])/'buehne.html.pre-gpt56-qa'
if not backup.exists(): backup.write_text(s,encoding='utf-8')
old='''function mikroSakkadeSchritt(){
  const winkel = Math.random() * Math.PI * 2;
  const staerke = 1.1 + Math.random() * 1.6; // 1.1-2.7px, klein
  mikroSakX = Math.cos(winkel) * staerke;
  mikroSakY = Math.sin(winkel) * staerke;
  setTimeout(() => { mikroSakX = 0; mikroSakY = 0; }, 80 + Math.random() * 90); // kurz gehalten, dann ballistisch zurueck (kein Lerp)
  setTimeout(mikroSakkadeSchritt, 1000 + Math.random() * 3000); // 1-4s, unregelmaessig
}
setTimeout(mikroSakkadeSchritt, 1500);'''
new='''function mikroSakkadeSchritt(){
  // Contract: microsaccades exist only while a real, near face is observed.
  if(!gazeBasisSichtbar()){
    mikroSakX = 0; mikroSakY = 0;
    setTimeout(mikroSakkadeSchritt, 250 + Math.random() * 450);
    return;
  }
  const winkel = Math.random() * Math.PI * 2;
  const staerke = 1.1 + Math.random() * 1.6; // conservative px proxy for ~0.2-0.7 deg
  mikroSakX = Math.cos(winkel) * staerke;
  mikroSakY = Math.sin(winkel) * staerke;
  setTimeout(() => { mikroSakX = 0; mikroSakY = 0; }, 80 + Math.random() * 90);
  setTimeout(mikroSakkadeSchritt, 250 + Math.random() * 450); // 250-700 ms contract cadence
}
setTimeout(mikroSakkadeSchritt, 250 + Math.random() * 450);'''
assert s.count(old)==1, ('micro_anchor',s.count(old)); s=s.replace(old,new,1)
old2='''let _atmenTransform = "scale(1)";
let _atmenFilter = "saturate(1.05) brightness(1)";
function atmen(){
  atemPhase += 0.006 * Math.max(0.4, Math.min(1.6, tempo));
  _mikroUnruhe += (_mikroUnruheZiel - _mikroUnruhe) * 0.02; // sehr langsam, kein Sprung'''
new2='''let _atmenTransform = "scale(1)";
let _atmenFilter = "saturate(1.05) brightness(1)";
let _atemLetzteZeit = null;
let _atemPeriodeMs = 4700;
let _atemNaechsterPeriodenwechsel = 0;
function atmen(t){
  if(!Number.isFinite(t)) t = performance.now();
  if(_atemLetzteZeit === null) _atemLetzteZeit = t;
  const dtMs = Math.max(0, Math.min(50, t - _atemLetzteZeit));
  _atemLetzteZeit = t;
  if(t >= _atemNaechsterPeriodenwechsel){
    _atemPeriodeMs = 3800 + Math.random() * 1800; // contract: 3.8-5.6 s
    _atemNaechsterPeriodenwechsel = t + _atemPeriodeMs;
  }
  atemPhase += (Math.PI * 2 * dtMs) / _atemPeriodeMs;
  const unruheAlpha = 1 - Math.exp(-dtMs / 800);
  _mikroUnruhe += (_mikroUnruheZiel - _mikroUnruhe) * unruheAlpha;'''
assert s.count(old2)==1, ('breath_anchor',s.count(old2)); s=s.replace(old2,new2,1)
anchor='''let letzteFrames = [];
function fpsMessen(t){'''
qa='''// --- FRANK_QA v1: bounded runtime telemetry, invisible to composition ---
const __frankQa = {started:performance.now(),prevFrame:null,frameDeltas:[],longTasks:[],errors:[],lastPublish:0,maxFrames:7200,maxLongTasks:512,maxErrors:128};
function __qaPush(a,v,m){a.push(v);if(a.length>m)a.splice(0,a.length-m);}
function __qaPct(a,p){if(!a.length)return null;return a[Math.min(a.length-1,Math.max(0,Math.ceil(p*a.length)-1))];}
function __qaSnapshot(){
  const d=__frankQa.frameDeltas.slice().sort((a,b)=>a-b);
  const mem=performance.memory?{usedJSHeapSize:performance.memory.usedJSHeapSize,totalJSHeapSize:performance.memory.totalJSHeapSize,jsHeapSizeLimit:performance.memory.jsHeapSizeLimit}:null;
  return {schema:"FRANK_QA/v1",uptime_ms:Math.round(performance.now()-__frankQa.started),samples:d.length,p50_ms:__qaPct(d,.50),p95_ms:__qaPct(d,.95),p99_ms:__qaPct(d,.99),max_ms:d.length?d[d.length-1]:null,spikes_gt_50ms:d.filter(x=>x>50).length,fps_1s:window.__buehneFps||0,longtask_count:__frankQa.longTasks.length,longtask_total_ms:Math.round(__frankQa.longTasks.reduce((a,x)=>a+x.duration,0)*100)/100,recent_errors:__frankQa.errors.slice(-16),memory:mem,breathing_period_ms:Math.round(_atemPeriodeMs),face_gate:gazeBasisSichtbar()};
}
window.__frankQA={snapshot:__qaSnapshot};
try{new PerformanceObserver(list=>{for(const e of list.getEntries())__qaPush(__frankQa.longTasks,{start:e.startTime,duration:e.duration},__frankQa.maxLongTasks);}).observe({entryTypes:["longtask"]});}catch(_e){}
window.addEventListener("error",e=>__qaPush(__frankQa.errors,{type:"error",message:String(e.message||""),at:performance.now()},__frankQa.maxErrors));
window.addEventListener("unhandledrejection",e=>__qaPush(__frankQa.errors,{type:"rejection",message:String(e.reason||""),at:performance.now()},__frankQa.maxErrors));
function __qaFrame(t){
  if(__frankQa.prevFrame!==null)__qaPush(__frankQa.frameDeltas,t-__frankQa.prevFrame,__frankQa.maxFrames);
  __frankQa.prevFrame=t;
  if(t-__frankQa.lastPublish>=1000){
    __frankQa.lastPublish=t;let out=document.getElementById("frank-qa-metrics");
    if(!out){out=document.createElement("output");out.id="frank-qa-metrics";out.hidden=true;document.body.appendChild(out);}
    out.textContent=JSON.stringify(__qaSnapshot());
  }
}

let letzteFrames = [];
function fpsMessen(t){'''
assert s.count(anchor)==1, ('qa_anchor',s.count(anchor)); s=s.replace(anchor,qa,1)
old3='''function schleife(t){
  atmen();'''
new3='''function schleife(t){
  __qaFrame(t);
  atmen(t);'''
assert s.count(old3)==1, ('loop_anchor',s.count(old3)); s=s.replace(old3,new3,1)
p.write_text(s,encoding='utf-8')
print('PATCH_BYTES_DELTA',len(s.encode())-len(orig.encode()))
print('PATCH_SHA256',hashlib.sha256(s.encode()).hexdigest())
PY
echo '=== CONTRACT CHECKS ==='
grep -nE 'function mikroSakkadeSchritt|250 \+ Math.random\(\) \* 450|function atmen\(t\)|3800 \+ Math.random\(\) \* 1800|FRANK_QA/v1|__qaFrame\(t\)' "$ROOT/buehne.html" | head -80
! grep -Fq 'setTimeout(mikroSakkadeSchritt, 1000 + Math.random() * 3000)' "$ROOT/buehne.html"
! grep -Fq 'atemPhase += 0.006' "$ROOT/buehne.html"
python3 - <<'PY'
import os,pathlib
s=(pathlib.Path(os.environ['ROOT'])/'buehne.html').read_text()
print('script_tags',s.count('<script'),s.count('</script>'),'braces',s.count('{'),s.count('}'),'parens',s.count('('),s.count(')'))
assert s.count('FRANK_QA/v1')==1 and s.count('function schleife(t)')==1 and s.count('function atmen(t)')==1 and s.count('function mikroSakkadeSchritt()')==1
PY
echo '=== DIFF SUMMARY ==='
diff -u "$ROOT/buehne.html.pre-gpt56-qa" "$ROOT/buehne.html" | grep -E '^(@@|[-+]function mikro|[-+]function atmen|[-+]  atmen|[-+]  __qaFrame|[-+]const __frankQa|[-+]  setTimeout\(mikro)' | head -120 || true
echo PATCH_OK
